let store,storageError='',corruptRaw=null,recoveryBackup=null,storageConflict=false;
// Server visitors must not load an old personal journal from browser storage.
if(remote)store=createStore();else try{const loaded=loadJournal(localStorage,KEY);store=loaded.store;storageError=loaded.error;corruptRaw=loaded.corruptRaw;recoveryBackup=loaded.backup;}catch{store=createStore();storageError=t('Хранилище браузера недоступно. Скачивайте JSON для сохранения.');}
let browserUser=clone(store.workspaces.user),ownerBrowserLoaded=false;
