let toastTimer,modalReturnFocus=null,tickerPaused=(()=>{try{return JSON.parse(localStorage.getItem(UI_KEY)||'{}').tickerPaused===true}catch{return false}})(),lastTickerMinute=-1;
const openActivities=new Set(),activityLimits=new Map();
