let draggingCategory='',dropPosition='';
function clearDropGuide(){document.querySelectorAll('.drop-before,.drop-after,.dragging-category').forEach(row=>row.classList.remove('drop-before','drop-after','dragging-category'));dropPosition='';}
document.addEventListener('dragstart',event=>{const row=event.target.closest('[data-category-id][draggable="true"]');if(row){draggingCategory=row.dataset.categoryId;event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',draggingCategory);requestAnimationFrame(()=>row.classList.add('dragging-category'));}});
document.addEventListener('dragover',event=>{const row=event.target.closest('[data-category-id][draggable="true"]');if(!draggingCategory||!row||row.dataset.categoryId===draggingCategory){document.querySelectorAll('.drop-before,.drop-after').forEach(el=>el.classList.remove('drop-before','drop-after'));return;}event.preventDefault();event.dataTransfer.dropEffect='move';const before=event.clientY<row.getBoundingClientRect().top+row.getBoundingClientRect().height/2;dropPosition=before?'before':'after';document.querySelectorAll('.drop-before,.drop-after').forEach(el=>el.classList.remove('drop-before','drop-after'));row.classList.add(before?'drop-before':'drop-after');});
document.addEventListener('drop',event=>{const row=event.target.closest('[data-category-id][draggable="true"]'),from=draggingCategory,position=dropPosition;clearDropGuide();draggingCategory='';if(!row||!from||row.dataset.categoryId===from||!position)return;event.preventDefault();try{commit(w=>{const index=w.categories.findIndex(c=>c.id===from),target=w.categories.findIndex(c=>c.id===row.dataset.categoryId);if(index<0||target<0)throw new Error(t('Категория не найдена.'));const [item]=w.categories.splice(index,1);w.categories.splice(w.categories.findIndex(c=>c.id===row.dataset.categoryId)+(position==='after'?1:0),0,item);},t('Порядок категорий сохранён'));}catch(error){toast(error.message);}});
document.addEventListener('dragend',()=>{draggingCategory='';clearDropGuide();});

// Column widths belong to this browser; journal entries are unaffected.
document.addEventListener('pointerdown',event=>{const handle=event.target.closest('.column-resizer');if(!handle)return;const table=handle.closest('table'),col=table?.querySelector(`col[data-column="${handle.dataset.resizeColumn}"]`);if(!col)return;event.preventDefault();const index=+handle.dataset.resizeColumn,start=event.clientX,initial=journalColumn(index);handle.setPointerCapture(event.pointerId);const move=e=>{const width=Math.max(90,Math.min(900,initial+e.clientX-start));col.style.width=width+'px';table.style.width=(parseFloat(table.style.width)+width-(journalWidths[index]||initial))+'px';journalWidths[index]=width;};const end=()=>{handle.removeEventListener('pointermove',move);handle.removeEventListener('pointerup',end);handle.removeEventListener('pointercancel',end);try{localStorage.setItem('ritm-journal-widths',JSON.stringify(journalWidths));}catch{}};handle.addEventListener('pointermove',move);handle.addEventListener('pointerup',end);handle.addEventListener('pointercancel',end);});
document.addEventListener('keydown',event=>{const handle=event.target.closest('.column-resizer');if(!handle||!['ArrowLeft','ArrowRight'].includes(event.key))return;event.preventDefault();const index=+handle.dataset.resizeColumn,table=handle.closest('table'),col=table.querySelector(`col[data-column="${index}"]`),previous=journalColumn(index),width=Math.max(90,Math.min(900,previous+(event.key==='ArrowRight'?20:-20)));journalWidths[index]=width;col.style.width=width+'px';table.style.width=parseFloat(table.style.width)+width-previous+'px';try{localStorage.setItem('ritm-journal-widths',JSON.stringify(journalWidths));}catch{}});

document.addEventListener('keydown',event=>{if(event.key==='Escape'&&matrixExpanded&&!dialogRoot.querySelector('dialog')){matrixExpanded=false;render();}});
